36	import org.springframework.samples.petclinic.rest.advice.InvalidRequestException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	import org.springframework.util.StringUtils;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
65	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
66	     * and a dotted domain (e.g. {@code not-an-email}).
67	     */
68	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
69	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
70	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
71	
72	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
73	    private static final String DEFAULT_COUNTRY_CODE = "61";
74	
75	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
76	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
77	
78	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
79	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
102	        Collection<Owner> owners;
103	        if (lastName != null) {
104	            owners = this.clinicService.findOwnerByLastName(lastName);
105	        } else {
106	            owners = this.clinicService.findAllOwners();
107	        }
108	        if (owners.isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
117	        Owner owner = this.clinicService.findOwnerById(ownerId);
118	        if (owner == null) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
127	        List<String> missingFields = new ArrayList<>();
128	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
129	            missingFields.add("firstName");
130	        }
131	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
132	            missingFields.add("lastName");
133	        }
134	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
135	            missingFields.add("address");
136	        }
137	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
138	            missingFields.add("city");
139	        }
140	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
141	            missingFields.add("telephone");
142	        }
143	        if (!missingFields.isEmpty()) {
144	            throw new InvalidRequestException(missingFields);
145	        }
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
149	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
150	        owner.setTelephone(normalizedTelephone);
151	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
152	        owner.setEmail(normalizeEmail(owner.getEmail()));
153	        // Default the (optional) registration date to the server's current date when none was supplied.
154	        if (owner.getRegistrationDate() == null) {
155	            owner.setRegistrationDate(LocalDate.now());
156	        }
157	        // Reject the request if the E.164 telephone is already used by another owner.
158	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
159	            throw new DuplicateTelephoneException(normalizedTelephone);
160	        }
161	        this.clinicService.saveOwner(owner);
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
171	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
172	        if (currentOwner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        currentOwner.setAddress(ownerFieldsDto.getAddress());
176	        currentOwner.setCity(ownerFieldsDto.getCity());
177	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
178	        currentOwner.setLastName(ownerFieldsDto.getLastName());
179	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
180	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
181	        this.clinicService.saveOwner(currentOwner);
182	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
183	    }
184	
185	    /**
186	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
187	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
188	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
189	     * is returned lower-cased.
190	     *
191	     * @param email the raw email from the request payload, may be {@code null}
192	     * @return the lower-cased email, or {@code null} when none was provided
193	     */
194	    private String normalizeEmail(String email) {
195	        if (!StringUtils.hasText(email)) {
196	            return null;
197	        }
198	        if (!EMAIL_PATTERN.matcher(email).matches()) {
199	            throw new InvalidRequestException(List.of("email"));
200	        }
201	        return email.toLowerCase(Locale.ROOT);
202	    }
203	
204	    /**
205	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
206	     * already carries a leading '+' keeps its country code; otherwise the default country code
207	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
208	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
209	     * is thrown (mapped to 400 Bad Request).
210	     *
211	     * @param telephone the raw telephone from the request payload
